create extension if not exists pgcrypto;
create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null, description text not null default '', price numeric(12,2), category text not null default 'comida' check (category in ('comida','bebidas','estrella')), image_url text not null default '', image_path text not null default '', tag text not null default '', is_active boolean not null default true, is_featured boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.promotions (id uuid primary key default gen_random_uuid(), title text not null, description text not null default '', image_url text not null default '', starts_at timestamptz, ends_at timestamptz, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create or replace function public.is_rares_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $$;
alter table public.products enable row level security; alter table public.promotions enable row level security; alter table public.admin_users enable row level security;
drop policy if exists "Public reads active products" on public.products;
create policy "Public reads active products" on public.products for select to anon, authenticated using (is_active = true or public.is_rares_admin());
drop policy if exists "Admins manage products" on public.products;
create policy "Admins manage products" on public.products for all to authenticated using (public.is_rares_admin()) with check (public.is_rares_admin());
drop policy if exists "Public reads active promotions" on public.promotions;
create policy "Public reads active promotions" on public.promotions for select to anon, authenticated using (((is_active = true) and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at >= now())) or public.is_rares_admin());
drop policy if exists "Admins manage promotions" on public.promotions;
create policy "Admins manage promotions" on public.promotions for all to authenticated using (public.is_rares_admin()) with check (public.is_rares_admin());
drop policy if exists "Admins read admin list" on public.admin_users;
create policy "Admins read admin list" on public.admin_users for select to authenticated using (public.is_rares_admin());
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Public views product images" on storage.objects;
create policy "Public views product images" on storage.objects for select to anon, authenticated using (bucket_id='product-images');
drop policy if exists "Admins upload product images" on storage.objects;
create policy "Admins upload product images" on storage.objects for insert to authenticated with check (bucket_id='product-images' and public.is_rares_admin());
drop policy if exists "Admins update product images" on storage.objects;
create policy "Admins update product images" on storage.objects for update to authenticated using (bucket_id='product-images' and public.is_rares_admin()) with check (bucket_id='product-images' and public.is_rares_admin());
drop policy if exists "Admins delete product images" on storage.objects;
create policy "Admins delete product images" on storage.objects for delete to authenticated using (bucket_id='product-images' and public.is_rares_admin());
